def save_file(filename, title, intro, sections):
    full_path = os.path.join(BASE_DIR, filename)
    with open(full_path, "w", encoding="utf-8") as f:
        f.write(f"# {title}\n\n")
        f.write(f"> {intro}\n\n---\n\n")
        for sec_title, questions in sections.items():
            f.write(f"## {sec_title}\n\n")
            for q in questions:
                f.write(f"### 第 {q['num']} 题（P{q['page']}）\n\n")
                f.write(f"{q['stem']}\n\n")
                if q.get('options'):
                    f.write(f"{q['options']}\n\n")
                f.write(f"> **【课程】** 计算机组成原理\n")
                f.write(f"> **【章节】** {q['ch']} · {sec_title}\n\n---\n\n")
    total_q = sum(len(qs) for qs in sections.values())
    print(f"Saved: {filename} ({total_q} items)")

